// src/mascot-layout.ts
function mascotLayout(widget, button, image, settings) {
  let peeking, side = "right", mobileY = Math.max(8, window.innerHeight - 190);
  let roundPosition = widget.getPosition();
  const height = () => window.visualViewport?.height || window.innerHeight;
  function dock() {
    widget.moveTo(side === "left" ? 8 : window.innerWidth - 72, Math.max(8, Math.min(mobileY, height() - 92)));
    button.classList.toggle("peek-left", side === "left");
  }
  function sync(resized = false) {
    const next = window.innerWidth <= 600 && settings()?.mobilePeek !== false;
    if (next !== peeking) {
      if (next)
        roundPosition = widget.getPosition();
      peeking = next;
      button.classList.toggle("peek", next);
      image.src = next ? kazz_peek_default : kazz_curled_default;
      if (!next) {
        button.classList.remove("peek-left");
        widget.moveTo(roundPosition.x, roundPosition.y);
      }
      resized = true;
    }
    const size = settings()?.mascotSize || 110;
    widget.setSize(next ? 64 : size, next ? 84 : size);
    if (resized && next)
      dock();
    else if (resized) {
      const p = widget.getPosition();
      widget.moveTo(Math.max(8, Math.min(p.x, window.innerWidth - size - 8)), Math.max(8, Math.min(p.y, height() - size - 8)));
    }
  }
  return { sync, width: () => peeking ? 64 : settings()?.mascotSize || 110, settled() {
    const p = widget.getPosition();
    if (peeking) {
      side = p.x + 32 < window.innerWidth / 2 ? "left" : "right";
      mobileY = p.y;
      dock();
    } else
      roundPosition = p;
  } };
}

// src/shared.ts
var CHANNEL = "kazzware.v1";
var DEFAULTS = { connectionId: "", slop: ["a shiver ran down", "a testament to", "couldn’t help but", "could not help but", "orbs"], wholeWords: true, galleryEnabled: false, commentaryEnabled: false, commentaryDuration: 14, commentaryWidth: 280, commentaryInterval: 1, mobilePeek: true, interval: 5, format: "random", contextMessages: 30, mascotSize: 110, autoName: false, nameInterval: 20, timelineAuto: false, timelineInject: false, spoilersEnabled: false };
function object(value) {
  if (!value || typeof value !== "object" || Array.isArray(value))
    throw new Error("Expected an object.");
  return value;
}
function uniqueRange(source, selected) {
  if (!selected)
    return;
  const start = source.indexOf(selected);
  if (start < 0 || source.indexOf(selected, start + 1) >= 0)
    return;
  return { start, end: start + selected.length };
}
function slopHits(text, phrases, wholeWords) {
  return phrases.map((phrase) => {
    const escaped = phrase.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const pattern = wholeWords ? `(?<![\\p{L}\\p{N}_])${escaped}(?![\\p{L}\\p{N}_])` : escaped;
    return { phrase, count: Array.from(text.matchAll(new RegExp(pattern, "giu"))).length };
  }).filter((x) => x.count > 0);
}
function escapeHTML(text) {
  return text.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);
}

// src/feature-controls.ts
function renderFeatureControls(body, ui, feature, draft, onDraft) {
  const s = { ...ui.view().state.settings, ...draft }, commentary = feature === "commentary";
  const check = (key, label, enabled) => `<label class="check feature-toggle"><span>${label}</span><input class="${key}" type="checkbox" role="switch" ${enabled ? "checked" : ""}></label>`;
  body.innerHTML = `<div class="section-head"><h2>${commentary ? "Commentary" : "Chat naming"}</h2></div><form class="feature-form">${commentary ? `
    ${check("commentary-enabled", "Let Kazz comment", s.commentaryEnabled)}
    <p class="muted">A short aside from his widget. Never added to the roleplay.</p>
    <label class="field">Comment every <output class="interval-value">${s.commentaryInterval}</output> new messages / swipes<input class="commentary-interval" type="range" min="1" max="50" value="${s.commentaryInterval}"></label>
    <fieldset><legend>Keep the bubble</legend><div class="segments">${[[14, "Timed"], [0, "Until closed"]].map(([n, label]) => `<button type="button" data-duration="${n}" aria-pressed="${n === 0 === (s.commentaryDuration === 0)}">${label}</button>`).join("")}</div><label class="field duration-field" ${s.commentaryDuration === 0 ? "hidden" : ""}>Seconds<input class="commentary-duration" type="number" min="3" max="120" value="${s.commentaryDuration || 14}" ${s.commentaryDuration === 0 ? "disabled" : ""} required></label></fieldset>
    <fieldset><legend>Bubble size</legend><div class="segments">${[[220, "Small"], [280, "Medium"], [360, "Large"]].map(([n, label]) => `<button type="button" data-width="${n}" aria-pressed="${s.commentaryWidth === n}">${label}</button>`).join("")}</div><div class="bubble-preview" style="--preview-width:${s.commentaryWidth}px"><b>Kazz</b>That door is absolutely somebody’s problem.</div></fieldset>
    <p class="muted">New swipes count once. Uses Kazz’s connection.</p>
    ` : `
    ${check("auto-name", "Name this chat automatically", s.autoName)}
    <p class="muted">A searchable title that follows the story.</p>
    <label class="field">Rename every <output class="interval-value">${s.nameInterval}</output> new messages<input class="name-interval" type="range" min="10" max="50" value="${s.nameInterval}"></label>
    <p class="muted">First title on the next new message. Swipes don’t advance the count. Existing titles can be replaced; Undo is below.</p>
    `}<button class="primary ${commentary ? "save-commentary" : "save-naming"}" data-mutate>Save preferences</button></form>`;
  let { commentaryDuration: duration, commentaryWidth: width } = s;
  const read = () => commentary ? {
    commentaryEnabled: body.querySelector(".commentary-enabled").checked,
    commentaryInterval: Number(body.querySelector(".commentary-interval").value),
    commentaryDuration: duration === 0 ? 0 : Number(body.querySelector(".commentary-duration").value),
    commentaryWidth: width
  } : { autoName: body.querySelector(".auto-name").checked, nameInterval: Number(body.querySelector(".name-interval").value) };
  body.querySelectorAll("input").forEach((input) => input.addEventListener("input", () => {
    const current = read();
    onDraft(current);
    body.querySelector("output").textContent = String(commentary ? current.commentaryInterval : current.nameInterval);
  }));
  body.querySelectorAll("[data-duration]").forEach((button) => button.addEventListener("click", () => {
    duration = Number(button.dataset.duration);
    body.querySelector(".duration-field").hidden = duration === 0;
    body.querySelector(".commentary-duration").disabled = duration === 0;
    body.querySelectorAll("[data-duration]").forEach((b) => b.setAttribute("aria-pressed", String(b === button)));
    onDraft(read());
  }));
  body.querySelectorAll("[data-width]").forEach((button) => button.addEventListener("click", () => {
    width = Number(button.dataset.width);
    body.querySelectorAll("[data-width]").forEach((b) => b.setAttribute("aria-pressed", String(b === button)));
    body.querySelector(".bubble-preview").style.setProperty("--preview-width", `${width}px`);
    onDraft(read());
  }));
  body.querySelector("form").addEventListener("submit", (event) => {
    event.preventDefault();
    if (ui.busy())
      return;
    const next = { ...ui.view().state.settings, ...read() };
    onDraft({});
    ui.run("settings", { settings: next }, `${commentary ? "Commentary" : "Chat naming"} preferences saved for this chat.`);
  });
  if (!commentary) {
    const history = document.createElement("div");
    history.className = "name-history";
    history.innerHTML = `<button class="name-now" data-mutate>Name chat now</button>${[...ui.view().state.story.names].reverse().filter((n) => n.status !== "undone").map((n) => `<button data-name-undo="${escapeHTML(n.id)}" data-mutate>Undo title: ${escapeHTML(n.after)}</button>`).join("")}`;
    history.querySelector(".name-now").addEventListener("click", () => {
      ui.run("nameChat", {}, "Chat renamed. Previous title saved for Undo.");
    });
    history.querySelectorAll("[data-name-undo]").forEach((button) => button.addEventListener("click", () => {
      ui.run("undoName", { id: button.dataset.nameUndo }, "Previous chat title restored.");
    }));
    body.append(history);
  }
}

