var TABS = [["home", "← Home"], ["edit", "Editor"], ["slop", "De-slop"], ["chat", "Chat"], ["gallery", "Gallery"], ["notebook", "Notebook"], ["timeline", "Summary+"], ["swipes", "Swipes"], ["commentary", "Commentary"], ["naming", "Chat naming"], ["settings", "Settings"]];
